// CollectionsUpcomingSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/collections/upcoming/list/CollectionsUpcomingSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import CollectionsUpcomingActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const CollectionsUpcomingSchema = {
  entity: 'simukopa_collections_upcoming',
  label: 'Expected Collections',
  description: '',
  apiBase: apiRoutes.collectionsupcoming?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: CollectionsUpcomingActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'due', label: 'Installments Due', from: 'loan_installments' },
    { key: 'scheduled', label: 'Scheduled', from: 'loan_installments.total_amount', type: 'money' },
    { key: 'balance', label: 'Still Unpaid', from: 'loan_installments.balance_amount', type: 'money' },
    { key: 'likely', label: 'Likely to Collect', calc: 'round(balance * 0.85)', type: 'money' },
    { key: 'at_risk', label: 'At Risk', calc: 'balance - likely', type: 'money' },
  ],

  remarks: [
    { if: 'due == 0', tone: 'neutral', title: 'Nothing due', say: 'No installments fall due in {label}.' },
    { if: 'true', tone: 'neutral', title: 'Expected', say: '{balance} unpaid across {due} installments, so about {likely} should come in and {at_risk} may not.' },
  ],

  headline: '{label}: {balance} still to collect from {due} installments, {likely} likely and {at_risk} at risk.',
};
